-- Cap nhat lai du lieu bai viet Blog chuan tieng Viet Unicode co dau
UPDATE posts
SET title = N'5 phụ kiện giúp góc làm việc gọn gàng và hiệu quả hơn',
    brief_info = N'Gợi ý những món phụ kiện thiết thực để tối ưu không gian, tăng sự tập trung và cảm hứng làm việc mỗi ngày.',
    content = N'<h3>Bắt đầu từ những món đồ bạn dùng mỗi ngày</h3><p>Một góc làm việc gọn gàng không chỉ giúp bàn làm việc của bạn thẩm mỹ hơn mà còn trực tiếp nâng cao hiệu suất làm việc và sự tập trung suốt cả ngày.</p><h4>1. Bàn phím cơ nhỏ gọn (Layout 65% - 75%)</h4><p>Giải phóng diện tích bàn làm việc, tạo không gian di chuyển chuột thoải mái hơn.</p><h4>2. Chuột không dây công thái học</h4><p>Loại bỏ dây cáp vướng víu, thiết kế ôm tay giúp cổ tay không bị mỏi khi làm việc trong thời gian dài.</p><h4>3. Deskmat (Lót bàn làm việc cỡ lớn)</h4><p>Tạo điểm nhấn liền mạch cho setup, bảo vệ mặt bàn và mang lại cảm giác di chuột mượt mà êm ái.</p><h4>4. Kệ kê màn hình hoặc giá đỡ laptop</h4><p>Đưa màn hình lên tầm mắt vừa phải, giảm đau mỏi cổ vai gáy, đồng thời tạo thêm khoảng trống bên dưới để cất gọn bàn phím khi không dùng.</p><h4>5. Tai nghe chống ồn</h4><p>Giúp bạn dễ dàng tập trung vào công việc trong môi trường văn phòng hoặc tại nhà.</p>'
WHERE id = 10 OR code = 'BV000001';

UPDATE posts
SET title = N'Vì sao bàn phím cơ ngày càng được ưa chuộng?',
    brief_info = N'Khám phá những lý do khiến bàn phím cơ trở thành lựa chọn yêu thích của dân văn phòng và người sáng tạo.',
    content = N'<p>Trải nghiệm gõ phím tuyệt vời cùng cảm giác êm ái giúp tăng hiệu suất làm việc mỗi ngày.</p><h3>1. Cảm giác gõ phím vượt trội và chính xác</h3><p>Khác với bàn phím cao su thông thường, bàn phím cơ sử dụng switch riêng biệt cho từng phím, mang lại độ nảy tốt, phản hồi xúc giác rõ ràng và giảm thiểu mỏi ngón tay.</p><h3>2. Độ bền cao lên đến hàng chục triệu lần nhấn</h3><p>Tuổi thọ trung bình của một chiếc bàn phím cơ từ 50 đến 100 triệu lần nhấn, bền bỉ hơn gấp nhiều lần so với bàn phím màng truyền thống.</p><h3>3. Khả năng tùy biến linh hoạt</h3><p>Người dùng có thể dễ dàng thay đổi keycap, switch (Hot-swap), chọn layout phù hợp với nhu cầu và phong cách của bản thân.</p><h3>4. Thiết kế hiện đại, thẩm mỹ</h3><p>Bàn phím cơ hiện đại sở hữu thiết kế tối giản, tông màu thanh lịch phù hợp với mọi góc làm việc hiện đại.</p>'
WHERE id = 11 OR code = 'BV000002';

UPDATE posts
SET title = N'Chọn chuột không dây cho ngày làm việc dài',
    brief_info = N'Tiêu chí quan trọng khi chọn chuột không dây: thiết kế thoải mái, kết nối ổn định và thời lượng pin bền bỉ cho công việc liên tục.',
    content = N'<h3>Chuột không dây công thái học</h3><p>Lựa chọn chuột không dây mang lại sự tự do và thoải mái tối đa cho không gian làm việc của bạn.</p><h4>1. Form cầm công thái học (Ergonomic)</h4><p>Thiết kế nghiêng tự nhiên giúp cổ tay giữ đúng tư thế, hạn chế hội chứng ống cổ tay khi làm việc suốt 8-10 tiếng.</p><h4>2. Nút bấm Silent Click êm ái</h4><p>Không gây tiếng ồn, giữ không gian yên tĩnh và giúp bạn thoải mái làm việc tại văn phòng hay ban đêm.</p><h4>3. Đa kết nối linh hoạt</h4><p>Hỗ trợ cả Bluetooth và Receiver 2.4GHz, dễ dàng chuyển đổi nhanh giữa laptop, PC và máy tính bảng.</p><h4>4. Thời lượng pin ấn tượng</h4><p>Pin sạc Type-C tiện lợi hoặc pin AA sử dụng liên tục nhiều tháng mà không lo gián đoạn công việc.</p>'
WHERE id = 14 OR code = 'BV000003';

UPDATE posts
SET title = N'Cách chọn chuột không dây phù hợp với nhu cầu làm việc',
    brief_info = N'Tìm hiểu cách lựa chọn form chuột, DPI và chuẩn kết nối bluetooth hoặc wireless 2.4GHz phù hợp.',
    content = N'<h3>Tiêu chí chọn chuột không dây văn phòng</h3><p>Form cầm và độ phân giải DPI là yếu tố quan trọng nhất để bạn thao tác chuột chính xác và không bị mỏi tay.</p><h4>1. Kích thước và trọng lượng phù hợp</h4><p>Nên chọn kích thước vừa vặn với kích cỡ bàn tay (nhỏ, vừa hoặc lớn) và trọng lượng nhẹ để di chuyển linh hoạt.</p><h4>2. Độ nhạy DPI có thể điều chỉnh</h4><p>Dải DPI từ 800 đến 2400 giúp bạn dễ dàng tùy chỉnh tốc độ chuột cho các tác vụ văn phòng hoặc thiết kế đồ họa.</p><h4>3. Cảm biến quang học hoạt động trên nhiều bề mặt</h4><p>Cảm biến chất lượng cao giúp chuột lướt mượt mà trên mặt bàn gỗ, da hay mặt kính mà không cần lót chuột phức tạp.</p>'
WHERE id = 15 OR code = 'BV000004';

